// Developer-only importer. The application embeds the generated files; it never runs Node.
// Usage: node scripts/import-vscode-icons.mjs /path/to/vscode-icons
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { execFileSync } from 'node:child_process';
import { stripTypeScriptTypes } from 'node:module';
const source = process.argv[2];
if (!source) throw new Error('Pass the pinned vscode-icons checkout');
const revision = '814aab8318900f47efeae6f1c4691494ae764199';
if (execFileSync('git', ['-C', source, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim() !== revision) throw new Error(`Expected upstream revision ${revision}`);
const output = 'assets/vscode-icons';
fs.mkdirSync(`${output}/icons`, { recursive: true });
const load = (file, name, globals = {}) => {
  const ts = fs.readFileSync(path.join(source, 'src/iconsManifest', file), 'utf8')
    .replace(/^import[^;]+;\s*/gm, '').replace(`export const ${name}`, `const ${name}`);
  return vm.runInNewContext(`${stripTypeScriptTypes(ts)}\n;${name}`, globals);
};
const languages = load('languages.ts', 'languages');
const files = load('supportedExtensions.ts', 'extensions', { languages });
const folders = load('supportedFolders.ts', 'extensions');
const maps = { filenames: {}, extensions: {}, folders: {} };
const names = {}, extensions = {};
const pair = (prefix, entry, suffix = '') => [
  `${prefix}${entry.icon}${suffix}.svg`,
  `${prefix}${entry.light ? 'light_' : ''}${entry.icon}${suffix}.svg`,
];
const sorted = collection => collection.supported.filter(x => !x.disabled && x.icon).sort((a,b) => a.icon < b.icon ? -1 : a.icon > b.icon ? 1 : 0);
for (const entry of sorted(files)) {
  const icons = pair('file_type_', entry);
  for (const language of entry.languages || []) {
    for (const name of language.knownFilenames || []) maps.filenames[name.toLowerCase()] = icons;
    for (const ext of language.knownExtensions || []) maps.extensions[ext.toLowerCase()] = icons;
  }
  const keys = [...(entry.extensions || [])];
  for (const name of entry.filenamesGlob || []) for (const ext of entry.extensionsGlob || []) keys.push(`${name}.${ext}`);
  for (const key of keys) (entry.filename ? names : extensions)[key.toLowerCase().replace(entry.filename ? /^$/ : /^\./, '')] = icons;
}
Object.assign(maps.filenames, names);
Object.assign(maps.extensions, extensions);
for (const entry of sorted(folders)) {
  for (const name of entry.extensions || []) maps.folders[name.toLowerCase()] = [...pair('folder_type_', entry), ...pair('folder_type_', entry, '_opened')];
}
const artwork = new Set(['default_file.svg', 'default_folder.svg', 'default_folder_opened.svg']);
for (const map of Object.values(maps)) for (const list of Object.values(map)) for (const name of list) artwork.add(name);
const sortedArtwork = [...artwork].sort();
for (const name of sortedArtwork) fs.copyFileSync(path.join(source, 'icons', name), `${output}/icons/${name}`);
fs.writeFileSync(`${output}/mappings.json`, JSON.stringify(maps) + '\n');
const catalog = sortedArtwork.map(name => `    (${JSON.stringify(name)}, Icon { name: ${JSON.stringify(name)}, view: 32.0, body: include_str!("../../assets/vscode-icons/icons/${name}") }),`).join('\n');
fs.writeFileSync('src/desktop/file_icon_catalog.rs', `// Generated by scripts/import-vscode-icons.mjs; see assets/vscode-icons/NOTICE.md.\nuse rune::Icon;\n#[rustfmt::skip]\npub(super) static ARTWORK: &[(&str, Icon)] = &[\n${catalog}\n];\n`);
fs.copyFileSync(path.join(source, 'LICENSE'), `${output}/SOURCE-LICENSE-MIT`);
console.log(`${sortedArtwork.length} SVGs, ${Object.keys(maps.filenames).length} filenames, ${Object.keys(maps.extensions).length} extensions, ${Object.keys(maps.folders).length} folders`);
